/**
 * Crée un emplacement de cours prêt à recevoir le contenu exact fourni par l'utilisateur
 * (sans inventer ni altérer le contenu).
 */
function createCourseSlot(
  num: number,
  domaine: PhysicsDomainId,
  domaineNomArabe: string,
  domaineNomFrancais: string
): PhysicsChemistryCourse {
  const padded = String(num).padStart(2, '0');
  return {
    id: `pc-course-${padded}`,
    numero: padded,
    titre: `الدرس ${padded} — Cours ${padded}`,
    titreArabe: `الدرس ${padded}`,
    titreNeutreArabe: `الدرس ${padded} — ${domaineNomArabe}`,
    sousTitreNeutre: `المجال : ${domaineNomArabe} · العلوم الفيزيائية والتكنولوجيا — السنة الثالثة متوسط (3AM)`,
    titreFrancais: `Chapitre ${padded} · ${domaineNomFrancais} (3AM)`,
    matiere: 'العلوم الفيزيائية والتكنولوجيا — Physique-Chimie',
    niveau: '3AM — السنة الثالثة متوسط',
    domaine,
    domaineNomArabe,
    domaineNomFrancais,
    duree: '60 د',
    status: 'awaiting_content',
    objectifs: [],
    prerequis: [],
    introduction: '',
    sections: [],
    definitions: [],
    observations: [],
    experiences: [],
    explications: [],
    schemas: [],
    figures: [],
    tableaux: [],
    formules: [],
    exemples: [],
    activites: [],
    applications: [],
    questions: [],
    correction: [],
    vocabulaire: [],
    resume: [],
    pointsEssentiels: [],
  };
}

