              'بما أن نوعًا كيميائيًا جديدًا (CO₂) ظهر ولم يكن موجودًا بهذه الصورة قبل الاحتراق، فإن احتراق الكربون في الهواء تحول كيميائي. وفي هذا التحول نميز بين:\n• المتفاعلات (Réactifs) : هي الأنواع الكيميائية الموجودة قبل التحول والتي تشارك فيه وتُستهلك (الكربون C وثنائي الأكسجين O₂).\n• الناتج (Produit) : هو النوع الكيميائي الجديد المتشكل بعد التحول (ثنائي أكسيد الكربون CO₂).\n• ثنائي الأزوت (N₂) الموجود في الهواء لا يشارك في التحول الكيميائي فلا يظهر في نموذج التفاعل.',
