              '2. موازنة ذرات الهيدروجين (H) : لدينا 10 ذرات H في C₄H₁₀ ، وبما أن كل جزيء ماء يضم ذرتي H، نضع المعامل 5 أمام H₂O: C₄H₁₀(g) + O₂(g) ⟶ 4CO₂(g) + 5H₂O(l).',
              '3. موازنة ذرات الأكسجين (O) كخطوة مؤقتة : مجموع ذرات O في النواتج = (4 × 2) + (5 × 1) = 8 + 5 = 13 ذرة O. نضع الكسر 13/2 كخطوة مؤقتة أمام O₂: C₄H₁₀(g) + 13/2 O₂(g) ⟶ 4CO₂(g) + 5H₂O(l).',
