          explanation:
            'في المتفاعلات لدينا ذرتان من H وذرتان من O ، بينما في جزيء H₂O توجد ذرة O واحدة. نضع المعامل 2 أمام H₂O فيصبح لدينا 4 ذرات H وذرتا O في النواتج، ثم نضع المعامل 2 أمام H₂ في المتفاعلات.\nجدول التحقق :\n• نوع الذرة H : في المتفاعلات 2 × 2 = 4 ذرات H | في النواتج 2 × 2 = 4 ذرات H (متساوٍ وموزون ✓)\n• نوع الذرة O : في المتفاعلات 1 × 2 = 2 ذرتا O | في النواتج 2 × 1 = 2 ذرتا O (متساوٍ وموزون ✓)',
