          explanation:
            'في المتفاعلات لدينا ذرة Zn واحدة وذرتا O في O₂ ، بينما في ZnO لدينا ذرة Zn واحدة وذرة O واحدة. نضع المعامل 2 أمام ZnO ليصبح لدينا ذرتا O، ثم نضع المعامل 2 أمام Zn في المتفاعلات.\nجدول التحقق :\n• نوع الذرة Zn : في المتفاعلات 2 × 1 = 2 ذرتا Zn | في النواتج 2 × 1 = 2 ذرتا Zn (متساوٍ وموزون ✓)\n• نوع الذرة O : في المتفاعلات 1 × 2 = 2 ذرتا O | في النواتج 2 × 1 = 2 ذرتا O (متساوٍ وموزون ✓)',
