/**
 * BUG 1 Guard (Build & Preview) :
 * Vérifie à l'initialisation qu'aucun cours publié ("populated") ne contient de section vide.
 */
function validatePhysicsCoursesIntegrity(courses: PhysicsChemistryCourse[]): void {
  for (const c of courses) {
    if (c.status !== 'populated') continue;
    if (!c.sections || c.sections.length === 0) {
      throw new Error(`[Build Error] Le cours ${c.numero} (${c.titreArabe}) ne contient aucune section.`);
    }
    for (const sec of c.sections) {
      if (!sec.blocks || sec.blocks.length === 0) {
        throw new Error(
          `[Build Error] La section "${sec.number}. ${sec.titleArabic}" du Cours ${c.numero} est vide.`
        );
      }
    }
  }
}

